div.script:
document.addEventListener('DOMContentLoaded', function() {
    var lugaresData = ;
    if (!lugaresData || !lugaresData.length) return;
    var map = L.map('lugares-map').setView([lugaresData[0].lat, lugaresData[0].lng], 14);
    L.tileLayer('https://{s}.tile.openstreetmap.org/{z}/{x}/{y}.png', {
        attribution: '© OpenStreetMap contributors'
    }).addTo(map);
    lugaresData.forEach(function(l) {
        L.marker([l.lat, l.lng]).addTo(map)
            .bindPopup(`${l.name}`);
    });
});

template.script:
document.addEventListener('DOMContentLoaded', function() {
    // Mapeo de IDs de lugar a IDs de attachment
    var attachmentMap = {
        34: {grid: '28274', detail: '28275'},
        33: {grid: '28276', detail: '28277'},
        32: {grid: '28278', detail: '28279'}
    };

    // Reemplazar URLs de imágenes en el grid
    document.querySelectorAll('img[src*="/web/image/lugares.interes.historia/"]').forEach(function(img) {
        var match = img.src.match(/\/web\/image\/memoria\.viva\.historia\/(\d+)\/image_main_(grid|detail)/);
        if (match) {
            var lugarId = match[1];
            var tipo = match[2];
            if (attachmentMap[lugarId] && attachmentMap[lugarId][tipo]) {
                img.src = '/web/content/' + attachmentMap[lugarId][tipo];
            }
        }
    });
});

document.addEventListener('DOMContentLoaded', function() {
    var form = document.getElementById('submitLugarForm');
    var errorContainer = document.getElementById('formErrorContainer');
    var errorText = document.getElementById('formErrorText');
    var submitBtn = document.getElementById('submitBtn');
    var modoAuthField = document.getElementById('modo_auth_field');

    if (!form) return;

    // Función para mostrar errores en card roja
    function showError(message) {
        errorText.textContent = message;
        errorContainer.classList.remove('d-none');
        // Scroll al error
        errorContainer.scrollIntoView({ behavior: 'smooth', block: 'center' });
    }

    // Función para ocultar errores
    function hideError() {
        errorContainer.classList.add('d-none');
        errorText.textContent = '';
    }

    // Detectar cambio de tab para actualizar modo_auth
    var loginTab = document.getElementById('login-tab');
    var registroTab = document.getElementById('registro-tab');

    if (loginTab) {
        loginTab.addEventListener('shown.bs.tab', function() {
            modoAuthField.value = 'login';
            hideError();
        });
    }

    if (registroTab) {
        registroTab.addEventListener('shown.bs.tab', function() {
            modoAuthField.value = 'registro';
            hideError();
        });
    }

    form.addEventListener('submit', function(e) {
        e.preventDefault();
        hideError();

        var fd = new FormData(form);
        var modo = modoAuthField.value || 'registro';

        // Validaciones según el modo
        if (modo === 'registro') {
            var pass1 = fd.get('registro_password') || '';
            var pass2 = fd.get('registro_password_confirm') || '';
            if (pass1 !== pass2) {
                showError('Las contraseñas no coinciden. Por favor verifica.');
                return;
            }
            if (pass1.length < 6) {
                showError('La contraseña debe tener al menos 6 caracteres.');
                return;
            }
            var regEmail = fd.get('registro_email') || '';
            if (!regEmail) {
                showError('El email es obligatorio para crear una cuenta.');
                return;
            }
            var regDni = fd.get('dni_remitente') || '';
            if (!regDni || regDni.length < 5) {
                showError('El documento de identidad es obligatorio (mínimo 5 caracteres).');
                return;
            }
        } else if (modo === 'login') {
            var loginEmail = fd.get('login_email') || '';
            var loginPass = fd.get('login_password') || '';
            if (!loginEmail || !loginPass) {
                showError('Email y contraseña son obligatorios para iniciar sesión.');
                return;
            }
        }
        // Si modo === 'logueado', no se necesita validación de credenciales
        // Los datos del usuario vienen de los campos ocultos user_id/partner_id

        // Validar campos obligatorios del lugar
        var nombreLugar = fd.get('name') || '';
        var direccion = fd.get('direccion') || '';
        var descripcion = fd.get('description') || '';

        if (!nombreLugar) {
            showError('El nombre del lugar es obligatorio.');
            return;
        }
        if (!direccion) {
            showError('La dirección es obligatoria.');
            return;
        }
        if (!descripcion) {
            showError('La descripción corta es obligatoria.');
            return;
        }

        // Validar categoría obligatoria
        var categoriaId = fd.get('categoria_id') || '';
        if (!categoriaId) {
            showError('La categoría es obligatoria.');
            return;
        }

        // Validar teléfono obligatorio solo si el campo existe en el formulario
        var telefonoInput = form.querySelector('input[name="registro_telefono"]');
        if (telefonoInput) {
            var telefono = fd.get('registro_telefono') || '';
            if (!telefono || telefono.length < 5) {
                showError('El teléfono es obligatorio (mínimo 5 dígitos).');
                return;
            }
        }

        // Leer archivo de imagen y convertir a base64
        var imageInput = form.querySelector('input[name="image"]');
        var imageFile = imageInput && imageInput.files[0];

        // Validar tamaño de imagen (2MB = 2097152 bytes)
        if (imageFile && imageFile.size > 2097152) {
            showError('La imagen es demasiado grande. Máximo permitido: 2MB.');
            return;
        }

        // Mostrar estado de carga
        submitBtn.disabled = true;
        submitBtn.innerHTML = '<i class="fa fa-spinner fa-spin me-2"></i>Enviando...';

        function sendData(imageBase64) {
            // Preparar datos según el modo
            var requestData = {
                name: fd.get('name'),
                direccion: fd.get('direccion') || '',
                description: fd.get('description') || '',
                categoria_id: fd.get('categoria_id') || '',
                barrio: fd.get('barrio') || '',
                image_main: imageBase64 || ''
            };

            // Agregar datos según modo de autenticación
            if (modo === 'logueado') {
                // Usuario ya autenticado - enviar IDs
                requestData.modo_auth = 'logueado';
                requestData.user_id = fd.get('user_id') || '';
                requestData.partner_id = fd.get('partner_id') || '';
            } else if (modo === 'registro') {
                requestData.modo_auth = 'registro';
                requestData.dni_remitente = fd.get('dni_remitente') || '';
                requestData.login_email = fd.get('registro_email') || '';
                requestData.login_password = fd.get('registro_password') || '';
                requestData.publicador_nombre = fd.get('registro_nombre') || 'Usuario';
                requestData.publicador_email = fd.get('registro_email') || '';
                requestData.publicador_telefono = fd.get('registro_telefono') || '';
                requestData.password = fd.get('registro_password') || '';
            } else if (modo === 'login') {
                requestData.modo_auth = 'login';
                requestData.login_email = fd.get('login_email') || '';
                requestData.login_password = fd.get('login_password') || '';
            }

            fetch('/lugares_interes/api/submit', {
                method: 'POST',
                headers: {'Content-Type': 'application/json'},
                body: JSON.stringify(requestData)
            })
            .then(function(r) { 
                if (!r.ok) throw new Error('Error de conexión');
                return r.json(); 
            })
            .then(function(res) {
                var result = res.result || res;
                if (result.success) {
                    if (modo === 'login') {
                        // Ocultar form y mostrar mensaje de éxito
                        form.style.display = 'none';
                        var successDiv = document.createElement('div');
                        successDiv.className = 'alert alert-success text-center py-5';
                        successDiv.innerHTML = '<i class="fa fa-check-circle fa-3x mb-3 text-success"></i>' +
                            '<h4>¡Lugar enviado correctamente!</h4>' +
                            '<p>Has iniciado sesión con tu cuenta.</p>' +
                            '<p>La página se recargará en <strong id="contRecarga">7</strong> segundos...</p>';
                        form.parentNode.insertBefore(successDiv, form);

                        var seg = 7;
                        setInterval(function() {
                            seg = seg - 1;
                            var el = document.getElementById('contRecarga');
                            if (el) el.textContent = seg;
                        }, 1000);

                        setTimeout(function() { window.location.reload(); }, 7000);
                    } else if (modo === 'registro') {
                        // Modo registro - ocultar form y mostrar mensaje con reload
                        form.style.display = 'none';
                        var successDiv = document.createElement('div');
                        successDiv.className = 'alert alert-success text-center py-5';
                        successDiv.innerHTML = '<i class="fa fa-check-circle fa-3x mb-3 text-success"></i>' +
                            '<h4>¡Cuenta creada y lugar enviado!</h4>' +
                            '<p>Tu usuario ha sido creado exitosamente.</p>' +
                            '<p>Iniciando sesión automáticamente... La página se recargará en <strong id="contRecarga">7</strong> segundos...</p>';
                        form.parentNode.insertBefore(successDiv, form);

                        var seg = 7;
                        setInterval(function() {
                            seg = seg - 1;
                            var el = document.getElementById('contRecarga');
                            if (el) el.textContent = seg;
                        }, 1000);

                        setTimeout(function() { window.location.reload(); }, 7000);
                    } else {
                        // Modo logueado (usuario ya estaba autenticado)
                        // Mostrar notificación tipo toast sin recargar
                        var notificacion = document.createElement('div');
                        notificacion.className = 'alert alert-success alert-dismissible fade show mb-4';
                        notificacion.innerHTML = 
                            '<div class="d-flex align-items-center">' +
                                '<i class="fa fa-check-circle fa-2x me-3"></i>' +
                                '<div>' +
                                    '<h5 class="mb-1">¡Lugar enviado correctamente!</h5>' +
                                    '<p class="mb-0">Gracias por compartir tu lugar. Puedes enviar otro lugar si lo deseas.</p>' +
                                '</div>' +
                                '<button type="button" class="btn-close ms-auto" data-bs-dismiss="alert"></button>' +
                            '</div>';

                        form.parentNode.insertBefore(notificacion, form);

                        // Limpiar formulario para nuevo envío
                        form.reset();

                        // Scroll al mensaje
                        notificacion.scrollIntoView({ behavior: 'smooth', block: 'center' });

                        // Ocultar notificación automáticamente después de 8 segundos
                        setTimeout(function() {
                            if (notificacion.parentNode) {
                                notificacion.classList.remove('show');
                                setTimeout(function() {
                                    notificacion.remove();
                                }, 300);
                            }
                        }, 8000);
                    }
                } else {
                    showError(result.error || 'Error al enviar el lugar. Intenta nuevamente.');
                }
            })
            .catch(function(err) { 
                showError('Error de conexión. Por favor verifica tu conexión e intenta nuevamente.');
            })
            .finally(function() {
                submitBtn.disabled = false;
                submitBtn.innerHTML = '<i class="fa fa-paper-plane me-2"></i>Enviar lugar';
            });
        }

        if (imageFile) {
            var reader = new FileReader();
            reader.onload = function(e) {
                sendData(e.target.result);
            };
            reader.onerror = function() {
                showError('Error al leer la imagen. Intenta con otra foto.');
                submitBtn.disabled = false;
                submitBtn.innerHTML = '<i class="fa fa-paper-plane me-2"></i>Enviar lugar';
            };
            reader.readAsDataURL(imageFile);
        } else {
            sendData('');
        }
    });

    // ========================================
    // MANEJADOR DE LIKES (GRID DE FOTOS)
    // ========================================
    document.querySelectorAll('.like-btn').forEach(function(btn) {
        btn.addEventListener('click', async function(e) {
            e.preventDefault();
            e.stopPropagation();

            var lugarId = this.dataset.lugarId;
            var icon = document.getElementById('like-icon-' + lugarId);

            if (!icon) return;

            try {
                var response = await fetch('/lugares-de-interes/like/' + lugarId, {
                    method: 'POST',
                    headers: {'Content-Type': 'application/json'}
                });
                var data = await response.json();
                var result = data.result || data;

                if (result.success) {
                    // Cambiar icono a lleno
                    icon.classList.remove('fa-heart-o');
                    icon.classList.add('fa-heart');

                    // Actualizar contador de likes en el badge si existe
                    var card = btn.closest('.card');
                    if (card) {
                        var statsContainer = card.querySelector('.position-absolute.bottom-0');
                        if (statsContainer && result.like_count !== undefined) {
                            var likeBadge = statsContainer.querySelector('.fa-heart').parentNode;
                            if (likeBadge) {
                                likeBadge.innerHTML = '<i class="fa fa-heart text-danger me-1"></i>' + result.like_count;
                            }
                        }
                    }
                } else if (result.already_liked) {
                    // Ya había dado like - mantener lleno
                    icon.classList.remove('fa-heart-o');
                    icon.classList.add('fa-heart');
                }
            } catch (err) {
                console.error('Error al dar like:', err);
            }
        });
    });
});

