document.addEventListener('DOMContentLoaded', function() {
    var map = L.map('lugar-map').setView([, ], 16);
    L.tileLayer('https://{s}.tile.openstreetmap.org/{z}/{x}/{y}.png', {
        attribution: '© OpenStreetMap contributors'
    }).addTo(map);
    L.marker([, ]).addTo(map)
        .bindPopup('').openPopup();
});
